    <style>
        :root {
            --primary-gold: #dcb078;
            --dark-blue: #1a2332;
            --text-grey: #666;
            --text-light: #fff;
            --font-serif: "Georgia", "Times New Roman", serif;
            --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        body {
            font-family: var(--font-sans);
            color: #333;
            background-color: #f9f9f9;
            overflow-x: hidden;
        }

        /* Utilities */
        .container {
            max-width: 1200px;
            margin: 0 auto;
            padding: 0 20px;
        }

        a { text-decoration: none; color: inherit; transition: opacity 0.3s; }
        ul { list-style: none; }

        /* HEADER */
        header {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            z-index: 100;
            padding: 25px 50px;
            display: flex;
            justify-content: space-between;
            align-items: center;
        }

        .logo {
            font-family: var(--font-serif);
            font-size: 28px;
            color: white;
            font-style: italic;
            line-height: 1;
        }
        .logo span { font-size: 14px; font-weight: normal; letter-spacing: 1px; text-transform: uppercase; display: block; text-align: center; margin-top: 2px;}

        nav ul {
            display: flex;
            gap: 25px;
        }

        nav a {
            color: white;
            font-size: 11px;
            font-weight: bold;
            text-transform: uppercase;
            letter-spacing: 1px;
        }
        nav a:hover { color: var(--primary-gold); }

