            background-size: cover;
            background-position: center;
            display: flex;
            flex-direction: column;
            justify-content: center;
            align-items: center;
            text-align: center;
            color: white;
        }

        /* Overlay for readability */
        .hero::before {
            content: '';
            position: absolute;
            top: 0; left: 0; right: 0; bottom: 0;
            background: rgba(0,0,0,0.2);
        }

        .hero-content {
            position: relative;
            z-index: 10;
            max-width: 800px;
            padding: 0 20px;
        }

        .welcome-text {
            font-family: var(--font-serif);
            font-style: italic;
            font-size: 24px;
            color: var(--primary-gold);
            margin-bottom: 10px;
        }

        h1 {
            font-family: var(--font-sans);
            font-size: 56px;
            font-weight: 800;
            text-transform: uppercase;
            line-height: 1.1;
            margin-bottom: 20px;
            letter-spacing: 2px;
            text-shadow: 0 2px 4px rgba(0,0,0,0.3);
        }

        .hero-desc {
            font-size: 14px;
            line-height: 1.6;
            max-width: 650px;
            margin: 0 auto 30px;
            color: #eee;
        }

        .btn-hero {
            display: inline-block;
            background-color: var(--primary-gold);
            color: white;
            padding: 12px 35px;
            border-radius: 30px;
            font-weight: bold;
            font-size: 13px;
            text-transform: uppercase;
            letter-spacing: 1px;
            box-shadow: 0 4px 6px rgba(0,0,0,0.2);
            transition: transform 0.2s;
        }
        .btn-hero:hover { transform: translateY(-2px); background-color: #c99b63; }

        .phone-bar {
            position: absolute;
            bottom: 40px;
            left: 60px;
            z-index: 10;
            color: white;
            font-weight: bold;
            font-size: 14px;
            display: flex;
            align-items: center;
            gap: 10px;
        }

