        .wave-divider {
            position: relative;
            height: 100px;
            width: 100%;
            overflow: hidden;
            background-color: var(--dark-blue);
            margin-top: -50px; /* Pull up over hero */
            z-index: 20;
        }
        .wave-svg {
            position: absolute;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            fill: var(--dark-blue); /* Matches the section below */
        }

        /* MAIN CONTENT LAYOUT */
        .main-wrapper {
            display: flex;
            background-color: #fcfcfc;
            min-height: 1200px; /* Simulating long page content */
            position: relative;
