            flex-shrink: 0;
            margin-left: auto; /* Push to right */
        }

        .form-header {
            background-color: var(--primary-gold);
            color: white;
            padding: 12px 15px;
            margin: -30px -25px 25px -25px; /* Negative margin to stretch full width of container */
