            gap: 8px;
            justify-content: flex-end;
            margin-bottom: 15px;
        }
        .social-box {
            width: 28px;
            height: 28px;
            border: 1px solid #ddd;
            display: flex;
            align-items: center;
            justify-content: center;
            color: #888;
            font-size: 14px;
            border-radius: 2px;
        }

        .form-group {
            margin-bottom: 15px;
        }
        .form-control {
            width: 100%;
            padding: 12px;
            border: 1px solid #e0e0e0;
            background-color: #fdfdfd;
            font-size: 13px;
            color: #555;
            outline: none;
            border-radius: 2px;
        }
        .form-control:focus { border-color: var(--primary-gold); }

        .btn-submit {
            width: 100%;
            background-color: #dcb078;
            color: white;
            border: none;
            padding: 14px;
            font-weight: bold;
            text-transform: uppercase;
            cursor: pointer;
            font-size: 13px;
            margin-top: 10px;
            border-radius: 2px;
        }
        .btn-submit:hover { background-color: #c99b63; }

        /* VIDEO PLACEHOLDER */
        .video-section {
            width: 100%;
            height: 400px;
            background-color: #111;
            margin-top: 50px;
            display: flex;
            align-items: center;
            justify-content: center;
