        .footer-grid {
            display: grid;
            grid-template-columns: repeat(4, 1fr);
            gap: 40px;
            margin-bottom: 50px;
        }

        .footer-col h3 {
            font-size: 16px;
            text-transform: uppercase;
            margin-bottom: 25px;
            font-weight: 700;
            letter-spacing: 1px;
        }

        .footer-col p, .footer-col li {
            color: #bbb;
            line-height: 1.8;
            margin-bottom: 8px;
        }

        .contact-phone {
            color: var(--primary-gold);
            font-weight: bold;
            font-size: 14px;
            margin: 15px 0;
            display: block;
        }

        .footer-socials {
            display: flex;
            gap: 10px;
            margin-top: 20px;
        }
        .footer-socials div {
            width: 32px;
            height: 32px;
            border: 1px solid #444;
            display: flex;
            align-items: center;
            justify-content: center;
            color: #888;
            border-radius: 2px;
        }

        .copyright {
            text-align: center;
            border-top: 1px solid #2a3442;
            padding-top: 30px;
            color: #666;
            font-size: 11px;
        }

    </style>
</head>
